get related() {
  return this.mRelated;
},
set related(aValue) {
  this.ensureMutable();
  switch (aValue) {
    case Ci.calIAlarm.ALARM_RELATED_ABSOLUTE:
      this.mOffset = null;
      break;
    case Ci.calIAlarm.ALARM_RELATED_START:
    case Ci.calIAlarm.ALARM_RELATED_END:
      this.mAbsoluteDate = null;
      break;
  }

  this.mRelated = aValue;
},
